/*
 * A106702  Infinite word generated by the morphism 1->3, 2->1, 3->24, 4->68,
 *          5->3, 6->78, 7->8, 8->46 starting from 13.
 * https://oeis.org/A106702
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
   Infinite word generated by the morphism  
   1 → 3,  2 → 1,  3 → 24,  4 → 68,  5 → 3,  6 → 78,  7 → 8,  8 → 46  
   starting from the seed word "13".  
   The sequence a(0)=1, a(1)=3, a(2)=3, a(3)=2, … is the left‑to‑right infinite
   word obtained by repeatedly appending the image of the current word.
   The implementation grows the word on demand up to the requested index
   and stores it in a static array.  For n≤10 000 the array never exceeds
   a few tens of thousands elements, well within time limits.
*/
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

static const int child_cnt[9] = {
    0, /* 0 unused */
    1, /* 1 → 3      */
    1, /* 2 → 1      */
    2, /* 3 → 24     */
    2, /* 4 → 68     */
    1, /* 5 → 3      */
    2, /* 6 → 78     */
    1, /* 7 → 8      */
    2  /* 8 → 46     */
};

static const int child_map[9][2] = {
    {0,0},          /* 0 unused */
    {3,0},          /* 1 → 3 */
    {1,0},          /* 2 → 1 */
    {2,4},          /* 3 → 24 */
    {6,8},          /* 4 → 68 */
    {3,0},          /* 5 → 3 */
    {7,8},          /* 6 → 78 */
    {8,0},          /* 7 → 8 */
    {4,6}           /* 8 → 46 */
};

seq_t a(idx_t n)
{
    /* static storage for the word built up to the greatest requested index */
    static seq_t *word = NULL;
    static size_t word_size = 0;

    /* initialise with the seed word "13" on the first call */
    if (word == NULL) {
        word = (seq_t *)malloc(2 * sizeof(seq_t));
        word[0] = (seq_t)1;
        word[1] = (seq_t)3;
        word_size = 2;
    }

    /* grow the word until it contains index n */
    while ((size_t)n >= word_size) {
        /* compute the length of the next word */
        size_t new_len = word_size;
        for (size_t i = 0; i < word_size; ++i) {
            new_len += (size_t)child_cnt[(int)word[i]];
        }

        /* allocate and build the new word */
        seq_t *new_word = (seq_t *)malloc(new_len * sizeof(seq_t));
        /* copy the current word */
        for (size_t i = 0; i < word_size; ++i) {
            new_word[i] = word[i];
        }
        /* append the images of the current word */
        size_t pos = word_size;
        for (size_t i = 0; i < word_size; ++i) {
            int sym = (int)word[i];
            int cnt = child_cnt[sym];
            if (cnt == 1) {
                new_word[pos++] = (seq_t)child_map[sym][0];
            } else { /* cnt == 2 */
                new_word[pos++] = (seq_t)child_map[sym][0];
                new_word[pos++] = (seq_t)child_map[sym][1];
            }
        }

        /* free the old word and replace it */
        free(word);
        word = new_word;
        word_size = new_len;
    }

    return word[(size_t)n];
}
